window.WPR_NORMEN = {
'13': 'Verbraucher ist jede natürliche Person, die ein Rechtsgeschäft zu Zwecken abschließt, die überwiegend weder ihrer gewerblichen noch ihrer selbständigen beruflichen Tätigkeit zugerechnet werden können.',
'14': 'Unternehmer ist eine natürliche oder juristische Person oder eine rechtsfähige Personengesellschaft, die bei Abschluss eines Rechtsgeschäfts in Ausübung ihrer gewerblichen oder selbständigen beruflichen Tätigkeit handelt.',
'94': '(1) Zu den wesentlichen Bestandteilen eines Grundstücks gehören die mit dem Grund und Boden fest verbundenen Sachen, insbesondere Gebäude … (2) Zu den wesentlichen Bestandteilen eines Gebäudes gehören die zur Herstellung des Gebäudes eingefügten Sachen.',
'104': 'Geschäftsunfähig ist: 1. wer nicht das siebente Lebensjahr vollendet hat, 2. wer sich in einem die freie Willensbestimmung ausschließenden Zustand krankhafter Störung der Geistestätigkeit befindet …',
'105': '(1) Die Willenserklärung eines Geschäftsunfähigen ist nichtig. (2) Nichtig ist auch eine Willenserklärung, die im Zustand der Bewusstlosigkeit oder vorübergehender Störung der Geistestätigkeit abgegeben wird.',
'105a': 'Tätigt ein volljähriger Geschäftsunfähiger ein Geschäft des täglichen Lebens, das mit geringwertigen Mitteln bewirkt werden kann, so gilt der von ihm geschlossene Vertrag … als wirksam, sobald Leistung und Gegenleistung bewirkt sind.',
'106': 'Ein Minderjähriger, der das siebente Lebensjahr vollendet hat, ist nach Maßgabe der §§ 107 bis 113 in der Geschäftsfähigkeit beschränkt.',
'107': 'Der Minderjährige bedarf zu einer Willenserklärung, durch die er nicht lediglich einen rechtlichen Vorteil erlangt, der Einwilligung seines gesetzlichen Vertreters.',
'108 I': 'Schließt der Minderjährige einen Vertrag ohne die erforderliche Einwilligung des gesetzlichen Vertreters, so hängt die Wirksamkeit des Vertrags von der Genehmigung des Vertreters ab.',
'108 II': 'Fordert der andere Teil den Vertreter zur Erklärung über die Genehmigung auf, so kann die Erklärung nur ihm gegenüber erfolgen … Die Genehmigung kann nur bis zum Ablauf von zwei Wochen nach dem Empfang der Aufforderung erklärt werden; wird sie nicht erklärt, so gilt sie als verweigert.',
'109': '(1) Bis zur Genehmigung des Vertrags ist der andere Teil zum Widerruf berechtigt … (2) Hat der andere Teil die Minderjährigkeit gekannt, so kann er nur widerrufen, wenn der Minderjährige der Wahrheit zuwider die Einwilligung des Vertreters behauptet hat …',
'110': 'Ein von dem Minderjährigen ohne Zustimmung des gesetzlichen Vertreters geschlossener Vertrag gilt als von Anfang an wirksam, wenn der Minderjährige die vertragsmäßige Leistung mit Mitteln bewirkt, die ihm zu diesem Zweck oder zu freier Verfügung … überlassen worden sind.',
'113': 'Ermächtigt der gesetzliche Vertreter den Minderjährigen, in Dienst oder in Arbeit zu treten, so ist der Minderjährige für solche Rechtsgeschäfte unbeschränkt geschäftsfähig, welche die Eingehung oder Aufhebung eines Dienst- oder Arbeitsverhältnisses … betreffen.',
'119 I': 'Wer bei der Abgabe einer Willenserklärung über deren Inhalt im Irrtum war oder eine Erklärung dieses Inhalts überhaupt nicht abgeben wollte, kann die Erklärung anfechten, wenn anzunehmen ist, dass er sie bei Kenntnis der Sachlage und bei verständiger Würdigung des Falles nicht abgegeben haben würde.',
'119 II': 'Als Irrtum über den Inhalt der Erklärung gilt auch der Irrtum über solche Eigenschaften der Person oder der Sache, die im Verkehr als wesentlich angesehen werden.',
'119': '(1) Wer bei der Abgabe einer Willenserklärung über deren Inhalt im Irrtum war oder eine Erklärung dieses Inhalts überhaupt nicht abgeben wollte, kann die Erklärung anfechten … (2) Als Irrtum über den Inhalt gilt auch der Irrtum über verkehrswesentliche Eigenschaften der Person oder der Sache.',
'120': 'Eine Willenserklärung, welche durch die zur Übermittlung verwendete Person oder Einrichtung unrichtig übermittelt worden ist, kann unter der gleichen Voraussetzung angefochten werden wie nach § 119 eine irrtümlich abgegebene Willenserklärung.',
'121': '(1) Die Anfechtung muss in den Fällen der §§ 119, 120 ohne schuldhaftes Zögern (unverzüglich) erfolgen, nachdem der Anfechtungsberechtigte von dem Anfechtungsgrund Kenntnis erlangt hat … (2) Die Anfechtung ist ausgeschlossen, wenn seit der Abgabe der Willenserklärung zehn Jahre verstrichen sind.',
'122': '(1) Ist eine Willenserklärung nach § 118 nichtig oder auf Grund der §§ 119, 120 angefochten, so hat der Erklärende … den Schaden zu ersetzen, den der andere dadurch erleidet, dass er auf die Gültigkeit der Erklärung vertraut, jedoch nicht über den Betrag des Interesses hinaus, welches der andere an der Gültigkeit der Erklärung hat. (2) Die Schadensersatzpflicht tritt nicht ein, wenn der Beschädigte den Grund der Nichtigkeit kannte oder kennen musste.',
'123 I': 'Wer zur Abgabe einer Willenserklärung durch arglistige Täuschung oder widerrechtlich durch Drohung bestimmt worden ist, kann die Erklärung anfechten.',
'123 II': 'Hat ein Dritter die Täuschung verübt, so ist eine Erklärung, die einem anderen gegenüber abzugeben war, nur dann anfechtbar, wenn dieser die Täuschung kannte oder kennen musste.',
'123': '(1) Wer zur Abgabe einer Willenserklärung durch arglistige Täuschung oder widerrechtlich durch Drohung bestimmt worden ist, kann die Erklärung anfechten. (2) Hat ein Dritter die Täuschung verübt, so ist die Erklärung nur anfechtbar, wenn der Empfänger die Täuschung kannte oder kennen musste.',
'124': '(1) Die Anfechtung einer nach § 123 anfechtbaren Willenserklärung kann nur binnen Jahresfrist erfolgen. (2) Die Frist beginnt im Falle der arglistigen Täuschung mit dem Zeitpunkt, in welchem der Anfechtungsberechtigte die Täuschung entdeckt, im Falle der Drohung mit dem Zeitpunkt, in welchem die Zwangslage aufhört …',
'125': 'Ein Rechtsgeschäft, welches der durch Gesetz vorgeschriebenen Form ermangelt, ist nichtig. Der Mangel der durch Rechtsgeschäft bestimmten Form hat im Zweifel gleichfalls Nichtigkeit zur Folge.',
'126': '(1) Ist durch Gesetz schriftliche Form vorgeschrieben, so muss die Urkunde von dem Aussteller eigenhändig durch Namensunterschrift … unterzeichnet werden. (3) Die schriftliche Form kann durch die elektronische Form ersetzt werden, wenn sich nicht aus dem Gesetz ein anderes ergibt.',
'126a': 'Soll die gesetzlich vorgeschriebene schriftliche Form durch die elektronische Form ersetzt werden, so muss der Aussteller der Erklärung dieser seinen Namen hinzufügen und das elektronische Dokument mit seiner qualifizierten elektronischen Signatur versehen.',
'126b': 'Ist durch Gesetz Textform vorgeschrieben, so muss eine lesbare Erklärung, in der die Person des Erklärenden genannt ist, auf einem dauerhaften Datenträger abgegeben werden.',
'128': 'Ist durch Gesetz notarielle Beurkundung eines Vertrags vorgeschrieben, so genügt es, wenn zunächst der Antrag und sodann die Annahme des Antrags von einem Notar beurkundet wird.',
'130': '(1) Eine Willenserklärung, die einem anderen gegenüber abzugeben ist, wird, wenn sie in dessen Abwesenheit abgegeben wird, in dem Zeitpunkt wirksam, in welchem sie ihm zugeht. Sie wird nicht wirksam, wenn dem anderen vorher oder gleichzeitig ein Widerruf zugeht.',
'133': 'Bei der Auslegung einer Willenserklärung ist der wirkliche Wille zu erforschen und nicht an dem buchstäblichen Sinne des Ausdrucks zu haften.',
'134': 'Ein Rechtsgeschäft, das gegen ein gesetzliches Verbot verstößt, ist nichtig, wenn sich nicht aus dem Gesetz ein anderes ergibt.',
'139': 'Ist ein Teil eines Rechtsgeschäfts nichtig, so ist das ganze Rechtsgeschäft nichtig, wenn nicht anzunehmen ist, dass es auch ohne den nichtigen Teil vorgenommen sein würde.',
'142': '(1) Wird ein anfechtbares Rechtsgeschäft angefochten, so ist es als von Anfang an nichtig anzusehen. (2) Wer die Anfechtbarkeit kannte oder kennen musste, wird … so behandelt, wie wenn er die Nichtigkeit des Rechtsgeschäfts gekannt hätte oder hätte kennen müssen.',
'143': '(1) Die Anfechtung erfolgt durch Erklärung gegenüber dem Anfechtungsgegner. (2) Anfechtungsgegner ist bei einem Vertrag der andere Teil …',
'145': 'Wer einem anderen die Schließung eines Vertrags anträgt, ist an den Antrag gebunden, es sei denn, dass er die Gebundenheit ausgeschlossen hat.',
'146': 'Der Antrag erlischt, wenn er dem Antragenden gegenüber abgelehnt oder wenn er nicht diesem gegenüber nach den §§ 147 bis 149 rechtzeitig angenommen wird.',
'147': '(1) Der einem Anwesenden gemachte Antrag kann nur sofort angenommen werden. Dies gilt auch von einem mittels Fernsprechers … gemachten Antrag. (2) Der einem Abwesenden gemachte Antrag kann nur bis zu dem Zeitpunkt angenommen werden, in welchem der Antragende den Eingang der Antwort unter regelmäßigen Umständen erwarten darf.',
'148': 'Hat der Antragende für die Annahme des Antrags eine Frist bestimmt, so kann die Annahme nur innerhalb der Frist erfolgen.',
'150': '(1) Die verspätete Annahme eines Antrags gilt als neuer Antrag. (2) Eine Annahme unter Erweiterungen, Einschränkungen oder sonstigen Änderungen gilt als Ablehnung verbunden mit einem neuen Antrag.',
'151': 'Der Vertrag kommt durch die Annahme des Antrags zustande, ohne dass die Annahme dem Antragenden gegenüber erklärt zu werden braucht, wenn eine solche Erklärung nach der Verkehrssitte nicht zu erwarten ist oder der Antragende auf sie verzichtet hat.',
'154': '(1) Solange nicht die Parteien sich über alle Punkte eines Vertrags geeinigt haben, über die nach der Erklärung auch nur einer Partei eine Vereinbarung getroffen werden soll, ist im Zweifel der Vertrag nicht geschlossen …',
'157': 'Verträge sind so auszulegen, wie Treu und Glauben mit Rücksicht auf die Verkehrssitte es erfordern.',
'158': '(1) Wird ein Rechtsgeschäft unter einer aufschiebenden Bedingung vorgenommen, so tritt die von der Bedingung abhängig gemachte Wirkung mit dem Eintritt der Bedingung ein.',
'164 I': 'Eine Willenserklärung, die jemand innerhalb der ihm zustehenden Vertretungsmacht im Namen des Vertretenen abgibt, wirkt unmittelbar für und gegen den Vertretenen. Es macht keinen Unterschied, ob die Erklärung ausdrücklich im Namen des Vertretenen erfolgt oder ob die Umstände ergeben, dass sie in dessen Namen erfolgen soll.',
'164 II': 'Tritt der Wille, in fremdem Namen zu handeln, nicht erkennbar hervor, so kommt der Mangel des Willens, im eigenen Namen zu handeln, nicht in Betracht.',
'164 III': 'Die Vorschriften des Absatzes 1 finden entsprechende Anwendung, wenn eine gegenüber einem anderen abzugebende Willenserklärung dessen Vertreter gegenüber erfolgt.',
'164': '(1) Eine Willenserklärung, die jemand innerhalb der ihm zustehenden Vertretungsmacht im Namen des Vertretenen abgibt, wirkt unmittelbar für und gegen den Vertretenen. (2) Tritt der Wille, in fremdem Namen zu handeln, nicht erkennbar hervor, so kommt der Mangel des Willens, im eigenen Namen zu handeln, nicht in Betracht.',
'165': 'Die Wirksamkeit einer von oder gegenüber einem Vertreter abgegebenen Willenserklärung wird nicht dadurch beeinträchtigt, dass der Vertreter in der Geschäftsfähigkeit beschränkt ist.',
'167': '(1) Die Erteilung der Vollmacht erfolgt durch Erklärung gegenüber dem zu Bevollmächtigenden oder dem Dritten, dem gegenüber die Vertretung stattfinden soll. (2) Die Erklärung bedarf nicht der Form, welche für das Rechtsgeschäft bestimmt ist, auf das sich die Vollmacht bezieht.',
'177': '(1) Schließt jemand ohne Vertretungsmacht im Namen eines anderen einen Vertrag, so hängt die Wirksamkeit des Vertrags für und gegen den Vertretenen von dessen Genehmigung ab.',
'179 I': 'Wer als Vertreter einen Vertrag geschlossen hat, ist, sofern er nicht seine Vertretungsmacht nachweist, dem anderen Teil nach dessen Wahl zur Erfüllung oder zum Schadensersatz verpflichtet, wenn der Vertretene die Genehmigung des Vertrags verweigert.',
'179 II': 'Hat der Vertreter den Mangel der Vertretungsmacht nicht gekannt, so ist er nur zum Ersatz desjenigen Schadens verpflichtet, welchen der andere Teil dadurch erleidet, dass er auf die Vertretungsmacht vertraut, jedoch nicht über den Betrag des Interesses hinaus, welches der andere an der Wirksamkeit des Vertrags hat.',
'179 III': 'Der Vertreter haftet nicht, wenn der andere Teil den Mangel der Vertretungsmacht kannte oder kennen musste. Der Vertreter haftet auch dann nicht, wenn er in der Geschäftsfähigkeit beschränkt war, es sei denn, dass er mit Zustimmung seines gesetzlichen Vertreters gehandelt hat.',
'179': '(1) Wer als Vertreter einen Vertrag geschlossen hat, ist, sofern er nicht seine Vertretungsmacht nachweist, dem anderen Teil nach dessen Wahl zur Erfüllung oder zum Schadensersatz verpflichtet, wenn der Vertretene die Genehmigung verweigert. (3) Der Vertreter haftet nicht, wenn der andere Teil den Mangel kannte oder kennen musste.',
'181': 'Ein Vertreter kann, soweit nicht ein anderes ihm gestattet ist, im Namen des Vertretenen mit sich im eigenen Namen oder als Vertreter eines Dritten ein Rechtsgeschäft nicht vornehmen, es sei denn, dass das Rechtsgeschäft ausschließlich in der Erfüllung einer Verbindlichkeit besteht.',
'182': '(1) Hängt die Wirksamkeit eines Vertrags … von der Zustimmung eines Dritten ab, so kann die Erteilung sowie die Verweigerung der Zustimmung sowohl dem einen als dem anderen Teil gegenüber erklärt werden.',
'184': '(1) Die nachträgliche Zustimmung (Genehmigung) wirkt auf den Zeitpunkt der Vornahme des Rechtsgeschäfts zurück, soweit nicht ein anderes bestimmt ist.',
'185': '(1) Eine Verfügung, die ein Nichtberechtigter über einen Gegenstand trifft, ist wirksam, wenn sie mit Einwilligung des Berechtigten erfolgt. (2) Die Verfügung wird wirksam, wenn der Berechtigte sie genehmigt oder wenn der Verfügende den Gegenstand erwirbt …',
'186': 'Für die in Gesetzen, gerichtlichen Verfügungen und Rechtsgeschäften enthaltenen Frist- und Terminsbestimmungen gelten die Auslegungsvorschriften der §§ 187 bis 193.',
'187': '(1) Ist für den Anfang einer Frist ein Ereignis oder ein in den Lauf eines Tages fallender Zeitpunkt maßgebend, so wird bei der Berechnung der Frist der Tag nicht mitgerechnet, in welchen das Ereignis oder der Zeitpunkt fällt. (2) Ist der Beginn eines Tages der für den Anfang einer Frist maßgebende Zeitpunkt, so wird dieser Tag bei der Berechnung der Frist mitgerechnet …',
'188': '(1) Eine nach Tagen bestimmte Frist endigt mit dem Ablauf des letzten Tages der Frist. (2) Eine Frist, die nach Wochen, nach Monaten oder nach einem mehrere Monate umfassenden Zeitraum bestimmt ist, endigt im Falle des § 187 Abs. 1 mit dem Ablauf desjenigen Tages der letzten Woche oder des letzten Monats, welcher durch seine Benennung oder seine Zahl dem Tage entspricht, in den das Ereignis fällt …',
'193': 'Ist an einem bestimmten Tage oder innerhalb einer Frist eine Willenserklärung abzugeben oder eine Leistung zu bewirken und fällt der bestimmte Tag oder der letzte Tag der Frist auf einen Sonntag, einen am Erklärungs- oder Leistungsort staatlich anerkannten allgemeinen Feiertag oder einen Sonnabend, so tritt an die Stelle eines solchen Tages der nächste Werktag.',
'195': 'Die regelmäßige Verjährungsfrist beträgt drei Jahre.',
'199': '(1) Die regelmäßige Verjährungsfrist beginnt … mit dem Schluss des Jahres, in dem 1. der Anspruch entstanden ist und 2. der Gläubiger von den den Anspruch begründenden Umständen und der Person des Schuldners Kenntnis erlangt oder ohne grobe Fahrlässigkeit erlangen müsste.',
'203': 'Schweben zwischen dem Schuldner und dem Gläubiger Verhandlungen über den Anspruch oder die den Anspruch begründenden Umstände, so ist die Verjährung gehemmt, bis der eine oder der andere Teil die Fortsetzung der Verhandlungen verweigert. Die Verjährung tritt frühestens drei Monate nach dem Ende der Hemmung ein.',
'204': '(1) Die Verjährung wird gehemmt durch 1. die Erhebung der Klage auf Leistung … 3. die Zustellung des Mahnbescheids im Mahnverfahren … (2) Die Hemmung … endet sechs Monate nach der rechtskräftigen Entscheidung oder anderweitigen Beendigung des eingeleiteten Verfahrens.',
'205': 'Die Verjährung ist gehemmt, solange der Schuldner auf Grund einer Vereinbarung mit dem Gläubiger vorübergehend zur Verweigerung der Leistung berechtigt ist.',
'212': '(1) Die Verjährung beginnt erneut, wenn 1. der Schuldner dem Gläubiger gegenüber den Anspruch durch Abschlagszahlung, Zinszahlung, Sicherheitsleistung oder in anderer Weise anerkennt oder 2. eine gerichtliche oder behördliche Vollstreckungshandlung vorgenommen oder beantragt wird.',
'214': '(1) Nach Eintritt der Verjährung ist der Schuldner berechtigt, die Leistung zu verweigern. (2) Das zur Befriedigung eines verjährten Anspruchs Geleistete kann nicht zurückgefordert werden, auch wenn in Unkenntnis der Verjährung geleistet worden ist …',
'241': '(1) Kraft des Schuldverhältnisses ist der Gläubiger berechtigt, von dem Schuldner eine Leistung zu fordern … (2) Das Schuldverhältnis kann nach seinem Inhalt jeden Teil zur Rücksicht auf die Rechte, Rechtsgüter und Interessen des anderen Teils verpflichten.',
'241a': '(1) Durch die Lieferung beweglicher Sachen, die nicht auf Grund gerichtlicher Maßnahmen … verkauft werden (Waren), oder durch die Erbringung sonstiger Leistungen durch einen Unternehmer an den Verbraucher wird ein Anspruch gegen den Verbraucher nicht begründet, wenn der Verbraucher die Waren oder sonstigen Leistungen nicht bestellt hat.',
'242': 'Der Schuldner ist verpflichtet, die Leistung so zu bewirken, wie Treu und Glauben mit Rücksicht auf die Verkehrssitte es erfordern.',
'243': '(1) Wer eine nur der Gattung nach bestimmte Sache schuldet, hat eine Sache von mittlerer Art und Güte zu leisten. (2) Hat der Schuldner das zur Leistung einer solchen Sache seinerseits Erforderliche getan, so beschränkt sich das Schuldverhältnis auf diese Sache.',
'246': 'Ist eine Schuld nach Gesetz oder Rechtsgeschäft zu verzinsen, so sind vier vom Hundert für das Jahr zu entrichten, sofern nicht ein anderes bestimmt ist.',
'249': '(1) Wer zum Schadensersatz verpflichtet ist, hat den Zustand herzustellen, der bestehen würde, wenn der zum Ersatz verpflichtende Umstand nicht eingetreten wäre.',
'252': 'Der zu ersetzende Schaden umfasst auch den entgangenen Gewinn. Als entgangen gilt der Gewinn, welcher nach dem gewöhnlichen Lauf der Dinge … mit Wahrscheinlichkeit erwartet werden konnte.',
'253': '(1) Wegen eines Schadens, der nicht Vermögensschaden ist, kann Entschädigung in Geld nur in den durch das Gesetz bestimmten Fällen gefordert werden. (2) Ist wegen einer Verletzung des Körpers, der Gesundheit, der Freiheit oder der sexuellen Selbstbestimmung Schadensersatz zu leisten, kann auch wegen des Schadens, der nicht Vermögensschaden ist, eine billige Entschädigung in Geld gefordert werden.',
'254': '(1) Hat bei der Entstehung des Schadens ein Verschulden des Beschädigten mitgewirkt, so hängt die Verpflichtung zum Ersatz sowie der Umfang des zu leistenden Ersatzes von den Umständen, insbesondere davon ab, inwieweit der Schaden vorwiegend von dem einen oder dem anderen Teil verursacht worden ist.',
'263': '(1) Die Wahl erfolgt durch Erklärung gegenüber dem anderen Teil. (2) Die gewählte Leistung gilt als die von Anfang an allein geschuldete.',
'269': '(1) Ist ein Ort für die Leistung weder bestimmt noch aus den Umständen … zu entnehmen, so hat die Leistung an dem Ort zu erfolgen, an welchem der Schuldner zur Zeit der Entstehung des Schuldverhältnisses seinen Wohnsitz hatte.',
'271': '(1) Ist eine Zeit für die Leistung weder bestimmt noch aus den Umständen zu entnehmen, so kann der Gläubiger die Leistung sofort verlangen, der Schuldner sie sofort bewirken.',
'273': '(1) Hat der Schuldner aus demselben rechtlichen Verhältnis, auf dem seine Verpflichtung beruht, einen fälligen Anspruch gegen den Gläubiger, so kann er … die geschuldete Leistung verweigern, bis die ihm gebührende Leistung bewirkt wird.',
'275': '(1) Der Anspruch auf Leistung ist ausgeschlossen, soweit diese für den Schuldner oder für jedermann unmöglich ist. (2) Der Schuldner kann die Leistung verweigern, soweit diese einen Aufwand erfordert, der … in einem groben Missverhältnis zu dem Leistungsinteresse des Gläubigers steht.',
'276': '(1) Der Schuldner hat Vorsatz und Fahrlässigkeit zu vertreten, wenn eine strengere oder mildere Haftung weder bestimmt noch aus dem sonstigen Inhalt des Schuldverhältnisses … zu entnehmen ist. (2) Fahrlässig handelt, wer die im Verkehr erforderliche Sorgfalt außer Acht lässt.',
'277': 'Wer nur für diejenige Sorgfalt einzustehen hat, welche er in eigenen Angelegenheiten anzuwenden pflegt, ist von der Haftung wegen grober Fahrlässigkeit nicht befreit.',
'278': 'Der Schuldner hat ein Verschulden seines gesetzlichen Vertreters und der Personen, deren er sich zur Erfüllung seiner Verbindlichkeit bedient, in gleichem Umfang zu vertreten wie eigenes Verschulden.',
'280 I': 'Verletzt der Schuldner eine Pflicht aus dem Schuldverhältnis, so kann der Gläubiger Ersatz des hierdurch entstehenden Schadens verlangen. Dies gilt nicht, wenn der Schuldner die Pflichtverletzung nicht zu vertreten hat.',
'280 II': 'Schadensersatz wegen Verzögerung der Leistung kann der Gläubiger nur unter der zusätzlichen Voraussetzung des § 286 verlangen.',
'280 III': 'Schadensersatz statt der Leistung kann der Gläubiger nur unter den zusätzlichen Voraussetzungen des § 281, des § 282 oder des § 283 verlangen.',
'280': '(1) Verletzt der Schuldner eine Pflicht aus dem Schuldverhältnis, so kann der Gläubiger Ersatz des hierdurch entstehenden Schadens verlangen. Dies gilt nicht, wenn der Schuldner die Pflichtverletzung nicht zu vertreten hat.',
'281': '(1) Soweit der Schuldner die fällige Leistung nicht oder nicht wie geschuldet erbringt, kann der Gläubiger … Schadensersatz statt der Leistung verlangen, wenn er dem Schuldner erfolglos eine angemessene Frist zur Leistung oder Nacherfüllung bestimmt hat. (2) Die Fristsetzung ist entbehrlich, wenn der Schuldner die Leistung ernsthaft und endgültig verweigert … (4) Der Anspruch auf die Leistung ist ausgeschlossen, sobald der Gläubiger statt der Leistung Schadensersatz verlangt hat.',
'283': 'Braucht der Schuldner nach § 275 Abs. 1 bis 3 nicht zu leisten, kann der Gläubiger unter den Voraussetzungen des § 280 Abs. 1 Schadensersatz statt der Leistung verlangen.',
'286 I': 'Leistet der Schuldner auf eine Mahnung des Gläubigers nicht, die nach dem Eintritt der Fälligkeit erfolgt, so kommt er durch die Mahnung in Verzug.',
'286 II': 'Der Mahnung bedarf es nicht, wenn 1. für die Leistung eine Zeit nach dem Kalender bestimmt ist, 2. der Leistung ein Ereignis vorauszugehen hat und eine angemessene Zeit … bestimmt ist, 3. der Schuldner die Leistung ernsthaft und endgültig verweigert, 4. aus besonderen Gründen … der sofortige Eintritt des Verzugs gerechtfertigt ist.',
'286 III': 'Der Schuldner einer Entgeltforderung kommt spätestens in Verzug, wenn er nicht innerhalb von 30 Tagen nach Fälligkeit und Zugang einer Rechnung … leistet; dies gilt gegenüber einem Schuldner, der Verbraucher ist, nur, wenn auf diese Folgen in der Rechnung … besonders hingewiesen worden ist.',
'286 IV': 'Der Schuldner kommt nicht in Verzug, solange die Leistung infolge eines Umstands unterbleibt, den er nicht zu vertreten hat.',
'286': '(1) Leistet der Schuldner auf eine Mahnung des Gläubigers nicht, die nach dem Eintritt der Fälligkeit erfolgt, so kommt er durch die Mahnung in Verzug. (4) Der Schuldner kommt nicht in Verzug, solange die Leistung infolge eines Umstands unterbleibt, den er nicht zu vertreten hat.',
'288': '(1) Eine Geldschuld ist während des Verzugs zu verzinsen. Der Verzugszinssatz beträgt für das Jahr fünf Prozentpunkte über dem Basiszinssatz. (2) Bei Rechtsgeschäften, an denen ein Verbraucher nicht beteiligt ist, beträgt der Zinssatz für Entgeltforderungen neun Prozentpunkte über dem Basiszinssatz. (5) Der Gläubiger einer Entgeltforderung hat bei Verzug eines Schuldners, der nicht Verbraucher ist, außerdem einen Anspruch auf Zahlung einer Pauschale in Höhe von 40 Euro.',
'293': 'Der Gläubiger kommt in Verzug, wenn er die ihm angebotene Leistung nicht annimmt.',
'294': 'Die Leistung muss dem Gläubiger so, wie sie zu bewirken ist, tatsächlich angeboten werden.',
'300': '(1) Der Schuldner hat während des Verzugs des Gläubigers nur Vorsatz und grobe Fahrlässigkeit zu vertreten. (2) Wird eine nur der Gattung nach bestimmte Sache geschuldet, so geht die Gefahr mit dem Zeitpunkt auf den Gläubiger über, in welchem er dadurch in Verzug kommt, dass er die angebotene Sache nicht annimmt.',
'305 I': 'Allgemeine Geschäftsbedingungen sind alle für eine Vielzahl von Verträgen vorformulierten Vertragsbedingungen, die eine Vertragspartei (Verwender) der anderen Vertragspartei bei Abschluss eines Vertrags stellt.',
'305 II': 'Allgemeine Geschäftsbedingungen werden nur dann Bestandteil eines Vertrags, wenn der Verwender bei Vertragsschluss 1. die andere Vertragspartei ausdrücklich … auf sie hinweist und 2. der anderen Vertragspartei die Möglichkeit verschafft, in zumutbarer Weise … von ihrem Inhalt Kenntnis zu nehmen, und wenn die andere Vertragspartei mit ihrer Geltung einverstanden ist.',
'305': '(1) Allgemeine Geschäftsbedingungen sind alle für eine Vielzahl von Verträgen vorformulierten Vertragsbedingungen, die eine Vertragspartei der anderen bei Abschluss eines Vertrags stellt. (2) Sie werden nur Bestandteil, wenn der Verwender ausdrücklich hinweist, zumutbare Kenntnisnahme ermöglicht und die andere Partei einverstanden ist.',
'305b': 'Individuelle Vertragsabreden haben Vorrang vor Allgemeinen Geschäftsbedingungen.',
'306': '(1) Sind Allgemeine Geschäftsbedingungen ganz oder teilweise nicht Vertragsbestandteil geworden oder unwirksam, so bleibt der Vertrag im Übrigen wirksam. (2) Soweit die Bestimmungen nicht Vertragsbestandteil geworden oder unwirksam sind, richtet sich der Inhalt des Vertrags nach den gesetzlichen Vorschriften.',
'307': '(1) Bestimmungen in Allgemeinen Geschäftsbedingungen sind unwirksam, wenn sie den Vertragspartner des Verwenders entgegen den Geboten von Treu und Glauben unangemessen benachteiligen. Eine unangemessene Benachteiligung kann sich auch daraus ergeben, dass die Bestimmung nicht klar und verständlich ist.',
'309': 'Auch soweit eine Abweichung von den gesetzlichen Vorschriften zulässig ist, ist in Allgemeinen Geschäftsbedingungen unwirksam … 7. a) ein Ausschluss oder eine Begrenzung der Haftung für Schäden aus der Verletzung des Lebens, des Körpers oder der Gesundheit … b) … für sonstige Schäden, die auf einer grob fahrlässigen Pflichtverletzung des Verwenders beruhen …',
'310': '(1) § 305 Absatz 2 und 3, § 308 Nummer 1, 2 bis 9 und § 309 finden keine Anwendung auf Allgemeine Geschäftsbedingungen, die gegenüber einem Unternehmer … verwendet werden. § 307 Abs. 1 und 2 findet … auch insoweit Anwendung, als dies zur Unwirksamkeit von in § 308 und § 309 genannten Vertragsbestimmungen führt …',
'311 I': 'Zur Begründung eines Schuldverhältnisses durch Rechtsgeschäft sowie zur Änderung des Inhalts eines Schuldverhältnisses ist ein Vertrag zwischen den Beteiligten erforderlich, soweit nicht das Gesetz ein anderes vorschreibt.',
'311 II': 'Ein Schuldverhältnis mit Pflichten nach § 241 Abs. 2 entsteht auch durch 1. die Aufnahme von Vertragsverhandlungen, 2. die Anbahnung eines Vertrags, bei welcher der eine Teil dem anderen Teil die Möglichkeit zur Einwirkung auf seine Rechte, Rechtsgüter und Interessen gewährt …, oder 3. ähnliche geschäftliche Kontakte.',
'311': '(1) Zur Begründung eines Schuldverhältnisses durch Rechtsgeschäft ist ein Vertrag erforderlich. (2) Ein Schuldverhältnis mit Pflichten nach § 241 Abs. 2 entsteht auch durch die Aufnahme von Vertragsverhandlungen, die Anbahnung eines Vertrags oder ähnliche geschäftliche Kontakte.',
'311a': '(1) Der Wirksamkeit eines Vertrags steht es nicht entgegen, dass der Schuldner nach § 275 Abs. 1 bis 3 nicht zu leisten braucht und das Leistungshindernis schon bei Vertragsschluss vorliegt. (2) Der Gläubiger kann nach seiner Wahl Schadensersatz statt der Leistung oder Ersatz seiner Aufwendungen … verlangen. Dies gilt nicht, wenn der Schuldner das Leistungshindernis bei Vertragsschluss nicht kannte und seine Unkenntnis auch nicht zu vertreten hat.',
'311b': '(1) Ein Vertrag, durch den sich der eine Teil verpflichtet, das Eigentum an einem Grundstück zu übertragen oder zu erwerben, bedarf der notariellen Beurkundung. Ein ohne Beachtung dieser Form geschlossener Vertrag wird seinem ganzen Inhalt nach gültig, wenn die Auflassung und die Eintragung in das Grundbuch erfolgen.',
'312a': '(1) Ruft der Unternehmer oder eine Person, die in seinem Namen oder Auftrag handelt, den Verbraucher an, um mit diesem einen Vertrag zu schließen, hat der Anrufer zu Beginn des Gesprächs seine Identität … und den geschäftlichen Zweck des Anrufs offenzulegen.',
'312c': '(1) Fernabsatzverträge sind Verträge, bei denen der Unternehmer … und der Verbraucher für die Vertragsverhandlungen und den Vertragsschluss ausschließlich Fernkommunikationsmittel verwenden, es sei denn, dass der Vertragsschluss nicht im Rahmen eines für den Fernabsatz organisierten Vertriebs- oder Dienstleistungssystems erfolgt.',
'312g': '(1) Dem Verbraucher steht bei außerhalb von Geschäftsräumen geschlossenen Verträgen und bei Fernabsatzverträgen ein Widerrufsrecht gemäß § 355 zu. (2) Das Widerrufsrecht besteht, soweit die Parteien nichts anderes vereinbart haben, nicht bei folgenden Verträgen: 1. Verträge zur Lieferung von Waren, die nicht vorgefertigt sind und für deren Herstellung eine individuelle Auswahl oder Bestimmung durch den Verbraucher maßgeblich ist … 2. … Waren, die schnell verderben können …',
'313': '(1) Haben sich Umstände, die zur Grundlage des Vertrags geworden sind, nach Vertragsschluss schwerwiegend verändert und hätten die Parteien den Vertrag nicht oder mit anderem Inhalt geschlossen, wenn sie diese Veränderung vorausgesehen hätten, so kann Anpassung des Vertrags verlangt werden, soweit … das Festhalten am unveränderten Vertrag nicht zugemutet werden kann. (3) Ist eine Anpassung nicht möglich oder einem Teil nicht zumutbar, so kann der benachteiligte Teil vom Vertrag zurücktreten.',
'314': '(1) Dauerschuldverhältnisse kann jeder Vertragsteil aus wichtigem Grund ohne Einhaltung einer Kündigungsfrist kündigen. (2) Besteht der wichtige Grund in der Verletzung einer Pflicht aus dem Vertrag, ist die Kündigung erst nach erfolglosem Ablauf einer zur Abhilfe bestimmten Frist oder nach erfolgloser Abmahnung zulässig.',
'320': '(1) Wer aus einem gegenseitigen Vertrag verpflichtet ist, kann die ihm obliegende Leistung bis zur Bewirkung der Gegenleistung verweigern, es sei denn, dass er vorzuleisten verpflichtet ist.',
'323 I': 'Erbringt bei einem gegenseitigen Vertrag der Schuldner eine fällige Leistung nicht oder nicht vertragsgemäß, so kann der Gläubiger, wenn er dem Schuldner erfolglos eine angemessene Frist zur Leistung oder Nacherfüllung bestimmt hat, vom Vertrag zurücktreten.',
'323 II': 'Die Fristsetzung ist entbehrlich, wenn 1. der Schuldner die Leistung ernsthaft und endgültig verweigert, 2. der Schuldner die Leistung bis zu einem im Vertrag bestimmten Termin … nicht bewirkt, obwohl … die termin- oder fristgerechte Leistung wesentlich ist, oder 3. … besondere Umstände vorliegen, die den sofortigen Rücktritt rechtfertigen.',
'323 V': 'Hat der Schuldner eine Teilleistung bewirkt, so kann der Gläubiger vom ganzen Vertrag nur zurücktreten, wenn er an der Teilleistung kein Interesse hat. Hat der Schuldner die Leistung nicht vertragsgemäß bewirkt, so kann der Gläubiger vom Vertrag nicht zurücktreten, wenn die Pflichtverletzung unerheblich ist.',
'323': '(1) Erbringt bei einem gegenseitigen Vertrag der Schuldner eine fällige Leistung nicht oder nicht vertragsgemäß, so kann der Gläubiger, wenn er dem Schuldner erfolglos eine angemessene Frist zur Leistung oder Nacherfüllung bestimmt hat, vom Vertrag zurücktreten. (5) … vom Vertrag nicht zurücktreten, wenn die Pflichtverletzung unerheblich ist.',
'325': 'Das Recht, bei einem gegenseitigen Vertrag Schadensersatz zu verlangen, wird durch den Rücktritt nicht ausgeschlossen.',
'326 I': 'Braucht der Schuldner nach § 275 Abs. 1 bis 3 nicht zu leisten, entfällt der Anspruch auf die Gegenleistung; bei einer Teilleistung findet § 441 Abs. 3 entsprechende Anwendung.',
'326 II': 'Ist der Gläubiger für den Umstand, auf Grund dessen der Schuldner nach § 275 nicht zu leisten braucht, allein oder weit überwiegend verantwortlich oder tritt dieser … Umstand zu einer Zeit ein, zu welcher der Gläubiger im Verzug der Annahme ist, so behält der Schuldner den Anspruch auf die Gegenleistung.',
'326 V': 'Braucht der Schuldner nach § 275 Abs. 1 bis 3 nicht zu leisten, kann der Gläubiger zurücktreten; auf den Rücktritt findet § 323 mit der Maßgabe entsprechende Anwendung, dass die Fristsetzung entbehrlich ist.',
'326': '(1) Braucht der Schuldner nach § 275 Abs. 1 bis 3 nicht zu leisten, entfällt der Anspruch auf die Gegenleistung. (2) Ist der Gläubiger … allein oder weit überwiegend verantwortlich oder befindet er sich im Annahmeverzug, so behält der Schuldner den Anspruch auf die Gegenleistung.',
'327': '(1) Die Vorschriften dieses Untertitels sind auf Verbraucherverträge anzuwenden, welche die Bereitstellung digitaler Inhalte oder digitaler Dienstleistungen … durch den Unternehmer gegen Zahlung eines Preises zum Gegenstand haben.',
'327c': '(1) Kommt der Unternehmer seiner fälligen Verpflichtung zur Bereitstellung des digitalen Produkts auf Aufforderung des Verbrauchers nicht unverzüglich nach, so kann der Verbraucher den Vertrag beenden.',
'327o': '(1) Die Beendigung des Vertrags erfolgt durch Erklärung gegenüber dem Unternehmer, in welcher der Entschluss des Verbrauchers zur Beendigung zum Ausdruck kommt.',
'346': '(1) Hat sich eine Vertragspartei vertraglich den Rücktritt vorbehalten oder steht ihr ein gesetzliches Rücktrittsrecht zu, so sind im Falle des Rücktritts die empfangenen Leistungen zurückzugewähren und die gezogenen Nutzungen herauszugeben.',
'355 I': 'Wird einem Verbraucher durch Gesetz ein Widerrufsrecht nach dieser Vorschrift eingeräumt, so sind der Verbraucher und der Unternehmer an ihre auf den Abschluss des Vertrags gerichteten Willenserklärungen nicht mehr gebunden, wenn der Verbraucher seine Willenserklärung fristgerecht widerrufen hat. Der Widerruf erfolgt durch Erklärung gegenüber dem Unternehmer. Aus der Erklärung muss der Entschluss des Verbrauchers zum Widerruf des Vertrags eindeutig hervorgehen. Der Widerruf muss keine Begründung enthalten. Zur Fristwahrung genügt die rechtzeitige Absendung des Widerrufs.',
'355 II': 'Die Widerrufsfrist beträgt 14 Tage. Sie beginnt mit Vertragsschluss, soweit nichts anderes bestimmt ist.',
'355': '(1) … Der Widerruf erfolgt durch Erklärung gegenüber dem Unternehmer … Der Widerruf muss keine Begründung enthalten. Zur Fristwahrung genügt die rechtzeitige Absendung des Widerrufs. (2) Die Widerrufsfrist beträgt 14 Tage. Sie beginnt mit Vertragsschluss, soweit nichts anderes bestimmt ist.',
'356': '(2) Die Widerrufsfrist beginnt 1. bei einem Verbrauchsgüterkauf, a) der nicht unter die Buchstaben b bis d fällt, sobald der Verbraucher … die Waren erhalten hat … (3) Die Widerrufsfrist beginnt nicht, bevor der Unternehmer den Verbraucher … unterrichtet hat. Das Widerrufsrecht erlischt spätestens zwölf Monate und 14 Tage nach dem in Absatz 2 … genannten Zeitpunkt.',
'357': '(1) Die empfangenen Leistungen sind spätestens nach 14 Tagen zurückzugewähren. … (5) Der Verbraucher trägt die unmittelbaren Kosten der Rücksendung der Waren, wenn der Unternehmer den Verbraucher … von dieser Pflicht unterrichtet hat.',
'357a': '(1) Der Verbraucher hat Wertersatz für einen Wertverlust der Ware zu leisten, wenn 1. der Wertverlust auf einen Umgang mit den Waren zurückzuführen ist, der zur Prüfung der Beschaffenheit, der Eigenschaften und der Funktionsweise der Waren nicht notwendig war, und 2. der Unternehmer den Verbraucher … über sein Widerrufsrecht unterrichtet hat.',
'361': '(2) Von den Vorschriften dieses Untertitels darf, soweit nicht ein anderes bestimmt ist, nicht zum Nachteil des Verbrauchers abgewichen werden.',
'362': '(1) Das Schuldverhältnis erlischt, wenn die geschuldete Leistung an den Gläubiger bewirkt wird.',
'363': 'Hat der Gläubiger eine ihm als Erfüllung angebotene Leistung als Erfüllung angenommen, so trifft ihn die Beweislast, wenn er die Leistung deshalb nicht als Erfüllung gelten lassen will, weil sie eine andere als die geschuldete … gewesen sei.',
'397': '(1) Das Schuldverhältnis erlischt, wenn der Gläubiger dem Schuldner durch Vertrag die Schuld erlässt.',
'398': 'Eine Forderung kann von dem Gläubiger durch Vertrag mit einem anderen auf diesen übertragen werden (Abtretung). Mit dem Abschluss des Vertrags tritt der neue Gläubiger an die Stelle des bisherigen Gläubigers.',
'399': 'Eine Forderung kann nicht abgetreten werden, wenn die Leistung an einen anderen als den ursprünglichen Gläubiger nicht ohne Veränderung ihres Inhalts erfolgen kann oder wenn die Abtretung durch Vereinbarung mit dem Schuldner ausgeschlossen ist.',
'407': '(1) Der neue Gläubiger muss eine Leistung, die der Schuldner nach der Abtretung an den bisherigen Gläubiger bewirkt … gegen sich gelten lassen, es sei denn, dass der Schuldner die Abtretung bei der Leistung … kennt.',
'433': '(1) Durch den Kaufvertrag wird der Verkäufer einer Sache verpflichtet, dem Käufer die Sache zu übergeben und das Eigentum an der Sache zu verschaffen. Der Verkäufer hat dem Käufer die Sache frei von Sach- und Rechtsmängeln zu verschaffen. (2) Der Käufer ist verpflichtet, dem Verkäufer den vereinbarten Kaufpreis zu zahlen und die gekaufte Sache abzunehmen.',
'434 I': 'Die Sache ist frei von Sachmängeln, wenn sie bei Gefahrübergang den subjektiven Anforderungen, den objektiven Anforderungen und den Montageanforderungen dieser Vorschrift entspricht.',
'434 II': 'Die Sache entspricht den subjektiven Anforderungen, wenn sie 1. die vereinbarte Beschaffenheit hat, 2. sich für die nach dem Vertrag vorausgesetzte Verwendung eignet und 3. mit dem vereinbarten Zubehör und den vereinbarten Anleitungen … übergeben wird.',
'434 III': 'Die Sache entspricht den objektiven Anforderungen, wenn sie 1. sich für die gewöhnliche Verwendung eignet, 2. eine Beschaffenheit aufweist, die bei Sachen derselben Art üblich ist und die der Käufer erwarten kann …',
'434': '(1) Die Sache ist frei von Sachmängeln, wenn sie bei Gefahrübergang den subjektiven Anforderungen, den objektiven Anforderungen und den Montageanforderungen dieser Vorschrift entspricht. (2) Subjektiv: vereinbarte Beschaffenheit, vertraglich vorausgesetzte Verwendung … (3) Objektiv: gewöhnliche Verwendung, übliche Beschaffenheit …',
'437': 'Ist die Sache mangelhaft, kann der Käufer, wenn die Voraussetzungen der folgenden Vorschriften vorliegen und soweit nicht ein anderes bestimmt ist, 1. nach § 439 Nacherfüllung verlangen, 2. nach den §§ 440, 323 und 326 Abs. 5 von dem Vertrag zurücktreten oder nach § 441 den Kaufpreis mindern und 3. nach den §§ 440, 280, 281, 283 und 311a Schadensersatz oder nach § 284 Ersatz vergeblicher Aufwendungen verlangen.',
'438': '(1) Die in § 437 Nr. 1 und 3 bezeichneten Ansprüche verjähren … 2. in fünf Jahren a) bei einem Bauwerk … 3. im Übrigen in zwei Jahren. (2) Die Verjährung beginnt bei Grundstücken mit der Übergabe, im Übrigen mit der Ablieferung der Sache. (3) Abweichend … verjähren die Ansprüche in der regelmäßigen Verjährungsfrist, wenn der Verkäufer den Mangel arglistig verschwiegen hat.',
'439 I': 'Der Käufer kann als Nacherfüllung nach seiner Wahl die Beseitigung des Mangels oder die Lieferung einer mangelfreien Sache verlangen.',
'439 II': 'Der Verkäufer hat die zum Zwecke der Nacherfüllung erforderlichen Aufwendungen, insbesondere Transport-, Wege-, Arbeits- und Materialkosten zu tragen.',
'439 III': 'Hat der Käufer die mangelhafte Sache gemäß ihrer Art und ihrem Verwendungszweck in eine andere Sache eingebaut oder an eine andere Sache angebracht, bevor der Mangel offenbar wurde, ist der Verkäufer im Rahmen der Nacherfüllung verpflichtet, dem Käufer die erforderlichen Aufwendungen für das Entfernen der mangelhaften und den Einbau oder das Anbringen der nachgebesserten oder gelieferten mangelfreien Sache zu ersetzen.',
'439 IV': 'Der Verkäufer kann die vom Käufer gewählte Art der Nacherfüllung … verweigern, wenn sie nur mit unverhältnismäßigen Kosten möglich ist …',
'439': '(1) Der Käufer kann als Nacherfüllung nach seiner Wahl die Beseitigung des Mangels oder die Lieferung einer mangelfreien Sache verlangen. (2) Der Verkäufer hat die zum Zwecke der Nacherfüllung erforderlichen Aufwendungen … zu tragen.',
'440': 'Außer in den Fällen des § 281 Absatz 2 und des § 323 Absatz 2 bedarf es der Fristsetzung auch dann nicht, wenn der Verkäufer beide Arten der Nacherfüllung gemäß § 439 Absatz 4 verweigert oder wenn die dem Käufer zustehende Art der Nacherfüllung fehlgeschlagen oder ihm unzumutbar ist. Eine Nachbesserung gilt nach dem erfolglosen zweiten Versuch als fehlgeschlagen …',
'441': '(1) Statt zurückzutreten, kann der Käufer den Kaufpreis durch Erklärung gegenüber dem Verkäufer mindern. Der Ausschlussgrund des § 323 Abs. 5 Satz 2 findet keine Anwendung. (3) Bei der Minderung ist der Kaufpreis in dem Verhältnis herabzusetzen, in welchem zur Zeit des Vertragsschlusses der Wert der Sache in mangelfreiem Zustand zu dem wirklichen Wert gestanden haben würde.',
'442': '(1) Die Rechte des Käufers wegen eines Mangels sind ausgeschlossen, wenn er bei Vertragsschluss den Mangel kennt. Ist dem Käufer ein Mangel infolge grober Fahrlässigkeit unbekannt geblieben, kann der Käufer Rechte wegen dieses Mangels nur geltend machen, wenn der Verkäufer den Mangel arglistig verschwiegen oder eine Garantie für die Beschaffenheit der Sache übernommen hat.',
'444': 'Auf eine Vereinbarung, durch welche die Rechte des Käufers wegen eines Mangels ausgeschlossen oder beschränkt werden, kann sich der Verkäufer nicht berufen, soweit er den Mangel arglistig verschwiegen oder eine Garantie für die Beschaffenheit der Sache übernommen hat.',
'446': 'Mit der Übergabe der verkauften Sache geht die Gefahr des zufälligen Untergangs und der zufälligen Verschlechterung auf den Käufer über … Der Übergabe steht es gleich, wenn der Käufer im Verzug der Annahme ist.',
'447': '(1) Versendet der Verkäufer auf Verlangen des Käufers die verkaufte Sache nach einem anderen Ort als dem Erfüllungsort, so geht die Gefahr auf den Käufer über, sobald der Verkäufer die Sache dem Spediteur, dem Frachtführer oder der sonst zur Ausführung der Versendung bestimmten Person … ausgeliefert hat.',
'449': '(1) Hat sich der Verkäufer einer beweglichen Sache das Eigentum bis zur Zahlung des Kaufpreises vorbehalten, so ist im Zweifel anzunehmen, dass das Eigentum unter der aufschiebenden Bedingung vollständiger Zahlung des Kaufpreises übertragen wird (Eigentumsvorbehalt).',
'474': '(1) Verbrauchsgüterkäufe sind Verträge, durch die ein Verbraucher von einem Unternehmer eine Ware (§ 241a Absatz 1) kauft. Um einen Verbrauchsgüterkauf handelt es sich auch bei einem Vertrag, der neben dem Verkauf einer Ware die Erbringung einer Dienstleistung durch den Unternehmer zum Gegenstand hat.',
'475': '(2) § 447 Absatz 1 ist mit der Maßgabe anzuwenden, dass die Gefahr des zufälligen Untergangs und der zufälligen Verschlechterung nur dann auf den Käufer übergeht, wenn der Käufer den Spediteur, den Frachtführer oder die sonst zur Ausführung der Versendung bestimmte Person … beauftragt hat und der Unternehmer dem Käufer diese Person … nicht zuvor benannt hat. (4) Der Verbraucher kann vom Unternehmer für Aufwendungen, die im Rahmen der Nacherfüllung … entstehen, Vorschuss verlangen.',
'475b': '(1) Für den Kauf einer Ware mit digitalen Elementen … gelten ergänzend die Regelungen dieser Vorschrift. (4) Eine Ware mit digitalen Elementen entspricht den objektiven Anforderungen, wenn … 2. dem Verbraucher während des Zeitraums, den er … erwarten kann, Aktualisierungen bereitgestellt werden … (5) Unterlässt es der Verbraucher, eine Aktualisierung … innerhalb einer angemessenen Frist zu installieren, so haftet der Unternehmer nicht für einen Sachmangel, der allein auf das Fehlen dieser Aktualisierung zurückzuführen ist, wenn … der Unternehmer den Verbraucher über die Verfügbarkeit der Aktualisierung und die Folgen einer unterlassenen Installation informiert hat …',
'475d': '(1) Zeigt sich ein Mangel, so bedarf es für den Rücktritt … abweichend von § 323 Absatz 1 und § 441 Absatz 1 Satz 1 der Bestimmung einer Frist zur Nacherfüllung nicht, wenn 1. der Unternehmer die Nacherfüllung trotz Ablaufs einer angemessenen Frist ab dem Zeitpunkt, zu dem der Verbraucher ihn über den Mangel unterrichtet hat, nicht vorgenommen hat …',
'476': '(1) Auf eine vor Mitteilung eines Mangels an den Unternehmer getroffene Vereinbarung, die zum Nachteil des Verbrauchers von den §§ 433 bis 435, 437, 439 bis 441 und 443 sowie von den Vorschriften dieses Untertitels abweicht, kann der Unternehmer sich nicht berufen. … (2) Die Verjährung der in § 437 bezeichneten Ansprüche kann vor Mitteilung eines Mangels an den Unternehmer nicht durch Rechtsgeschäft erleichtert werden, wenn die Vereinbarung zu einer Verjährungsfrist ab dem gesetzlichen Verjährungsbeginn von weniger als zwei Jahren, bei gebrauchten Sachen von weniger als einem Jahr führt …',
'477': '(1) Zeigt sich innerhalb eines Jahres seit Gefahrübergang ein von den Anforderungen nach § 434 oder § 475b abweichender Zustand der Ware, so wird vermutet, dass die Ware bereits bei Gefahrübergang mangelhaft war, es sei denn, diese Vermutung ist mit der Art der Ware oder des mangelhaften Zustands unvereinbar.',
'488': '(1) Durch den Darlehensvertrag wird der Darlehensgeber verpflichtet, dem Darlehensnehmer einen Geldbetrag in der vereinbarten Höhe zur Verfügung zu stellen. Der Darlehensnehmer ist verpflichtet, einen geschuldeten Zins zu zahlen und bei Fälligkeit das zur Verfügung gestellte Darlehen zurückzuzahlen. (3) Ist für die Rückzahlung des Darlehens eine Zeit nicht bestimmt, so hängt die Fälligkeit davon ab, dass der Darlehensgeber oder der Darlehensnehmer kündigt. Die Kündigungsfrist beträgt drei Monate. Sind Zinsen nicht geschuldet, so ist der Darlehensnehmer auch ohne Kündigung zur Rückzahlung berechtigt.',
'490': '(2) Der Darlehensnehmer kann einen Darlehensvertrag, bei dem der Sollzinssatz gebunden und das Darlehen durch ein Grund- oder Schiffspfandrecht gesichert ist, … vorzeitig kündigen, wenn seine berechtigten Interessen dies gebieten … Der Darlehensnehmer hat dem Darlehensgeber denjenigen Schaden zu ersetzen, der diesem aus der vorzeitigen Kündigung entsteht (Vorfälligkeitsentschädigung).',
'492': '(1) Allgemein-Verbraucherdarlehensverträge sind, soweit nicht eine strengere Form vorgeschrieben ist, schriftlich abzuschließen.',
'516': '(1) Eine Zuwendung, durch die jemand aus seinem Vermögen einen anderen bereichert, ist Schenkung, wenn beide Teile darüber einig sind, dass die Zuwendung unentgeltlich erfolgt.',
'518': '(1) Zur Gültigkeit eines Vertrags, durch den eine Leistung schenkweise versprochen wird, ist die notarielle Beurkundung des Versprechens erforderlich. (2) Der Mangel der Form wird durch die Bewirkung der versprochenen Leistung geheilt.',
'530': '(1) Eine Schenkung kann widerrufen werden, wenn sich der Beschenkte durch eine schwere Verfehlung gegen den Schenker oder einen nahen Angehörigen des Schenkers groben Undanks schuldig macht.',
'548': '(1) Die Ersatzansprüche des Vermieters wegen Veränderungen oder Verschlechterungen der Mietsache verjähren in sechs Monaten. Die Verjährung beginnt mit dem Zeitpunkt, in dem er die Mietsache zurückerhält …',
'611': '(1) Durch den Dienstvertrag wird derjenige, welcher Dienste zusagt, zur Leistung der versprochenen Dienste, der andere Teil zur Gewährung der vereinbarten Vergütung verpflichtet.',
'611a': '(1) Durch den Arbeitsvertrag wird der Arbeitnehmer im Dienste eines anderen zur Leistung weisungsgebundener, fremdbestimmter Arbeit in persönlicher Abhängigkeit verpflichtet.',
'614': 'Die Vergütung ist nach der Leistung der Dienste zu entrichten. Ist die Vergütung nach Zeitabschnitten bemessen, so ist sie nach dem Ablauf der einzelnen Zeitabschnitte zu entrichten.',
'622': '(1) Das Arbeitsverhältnis eines Arbeiters oder eines Angestellten (Arbeitnehmers) kann mit einer Frist von vier Wochen zum Fünfzehnten oder zum Ende eines Kalendermonats gekündigt werden.',
'623': 'Die Beendigung von Arbeitsverhältnissen durch Kündigung oder Auflösungsvertrag bedürfen zu ihrer Wirksamkeit der Schriftform; die elektronische Form ist ausgeschlossen.',
'631': '(1) Durch den Werkvertrag wird der Unternehmer zur Herstellung des versprochenen Werkes, der Besteller zur Entrichtung der vereinbarten Vergütung verpflichtet. (2) Gegenstand des Werkvertrags kann sowohl die Herstellung oder Veränderung einer Sache als auch ein anderer durch Arbeit oder Dienstleistung herbeizuführender Erfolg sein.',
'632a': '(1) Der Unternehmer kann von dem Besteller eine Abschlagszahlung in Höhe des Wertes der von ihm erbrachten und nach dem Vertrag geschuldeten Leistungen verlangen.',
'634': 'Ist das Werk mangelhaft, kann der Besteller … 1. nach § 635 Nacherfüllung verlangen, 2. nach § 637 den Mangel selbst beseitigen und Ersatz der erforderlichen Aufwendungen verlangen, 3. … zurücktreten oder … mindern und 4. … Schadensersatz oder … Ersatz vergeblicher Aufwendungen verlangen.',
'634a': '(1) Die in § 634 Nr. 1, 2 und 4 bezeichneten Ansprüche verjähren 1. … in zwei Jahren bei einem Werk, dessen Erfolg in der Herstellung, Wartung oder Veränderung einer Sache … besteht, 2. in fünf Jahren bei einem Bauwerk …, 3. im Übrigen in der regelmäßigen Verjährungsfrist.',
'640': '(1) Der Besteller ist verpflichtet, das vertragsmäßig hergestellte Werk abzunehmen, sofern nicht nach der Beschaffenheit des Werkes die Abnahme ausgeschlossen ist. Wegen unwesentlicher Mängel kann die Abnahme nicht verweigert werden. (2) Als abgenommen gilt ein Werk auch, wenn der Unternehmer dem Besteller nach Fertigstellung des Werks eine angemessene Frist zur Abnahme gesetzt hat und der Besteller die Abnahme nicht innerhalb dieser Frist unter Angabe mindestens eines Mangels verweigert hat …',
'641': '(1) Die Vergütung ist bei der Abnahme des Werkes zu entrichten.',
'650g': '(4) Die Vergütung ist zu entrichten, wenn 1. der Besteller das Werk abgenommen hat oder die Abnahme nach § 641 Absatz 2 entbehrlich ist und 2. der Unternehmer dem Besteller eine prüffähige Schlussrechnung erteilt hat.',
'657': 'Wer durch öffentliche Bekanntmachung eine Belohnung für die Vornahme einer Handlung, insbesondere für die Herbeiführung eines Erfolges, aussetzt, ist verpflichtet, die Belohnung demjenigen zu entrichten, welcher die Handlung vorgenommen hat, auch wenn dieser nicht mit Rücksicht auf die Auslobung gehandelt hat.',
'662': 'Durch die Annahme eines Auftrags verpflichtet sich der Beauftragte, ein ihm von dem Auftraggeber übertragenes Geschäft für diesen unentgeltlich zu besorgen.',
'670': 'Macht der Beauftragte zum Zwecke der Ausführung des Auftrags Aufwendungen, die er den Umständen nach für erforderlich halten darf, so ist der Auftraggeber zum Ersatz verpflichtet.',
'701': '(1) Ein Gastwirt, der gewerbsmäßig Fremde zur Beherbergung aufnimmt, hat den Schaden zu ersetzen, der durch den Verlust, die Zerstörung oder die Beschädigung von Sachen entsteht, die ein im Betrieb dieses Gewerbes aufgenommener Gast eingebracht hat.',
'702a': '(1) Die Haftung des Gastwirts kann im Voraus nur erlassen werden, soweit sie den nach § 702 Abs. 1 maßgeblichen Höchstbetrag übersteigt …',
'765': '(1) Durch den Bürgschaftsvertrag verpflichtet sich der Bürge gegenüber dem Gläubiger eines Dritten, für die Erfüllung der Verbindlichkeit des Dritten einzustehen.',
'766': 'Zur Gültigkeit des Bürgschaftsvertrags ist schriftliche Erteilung der Bürgschaftserklärung erforderlich. Die Erteilung der Bürgschaftserklärung in elektronischer Form ist ausgeschlossen. Soweit der Bürge die Hauptverbindlichkeit erfüllt, wird der Mangel der Form geheilt.',
'781': 'Zur Gültigkeit eines Vertrags, durch den das Bestehen eines Schuldverhältnisses anerkannt wird (Schuldanerkenntnis), ist schriftliche Erteilung der Anerkennungserklärung erforderlich …',
'812': '(1) Wer durch die Leistung eines anderen oder in sonstiger Weise auf dessen Kosten etwas ohne rechtlichen Grund erlangt, ist ihm zur Herausgabe verpflichtet. Diese Verpflichtung besteht auch dann, wenn der rechtliche Grund später wegfällt …',
'816': '(1) Trifft ein Nichtberechtigter über einen Gegenstand eine Verfügung, die dem Berechtigten gegenüber wirksam ist, so ist er dem Berechtigten zur Herausgabe des durch die Verfügung Erlangten verpflichtet … (2) Wird an einen Nichtberechtigten eine Leistung bewirkt, die dem Berechtigten gegenüber wirksam ist, so ist der Nichtberechtigte dem Berechtigten zur Herausgabe des Geleisteten verpflichtet.',
'818': '(1) Die Verpflichtung zur Herausgabe erstreckt sich auf die gezogenen Nutzungen … (2) Ist die Herausgabe wegen der Beschaffenheit des Erlangten nicht möglich …, so hat der Empfänger den Wert zu ersetzen. (3) Die Verpflichtung zur Herausgabe oder zum Ersatz des Wertes ist ausgeschlossen, soweit der Empfänger nicht mehr bereichert ist.',
'819': '(1) Kennt der Empfänger den Mangel des rechtlichen Grundes im Zeitpunkt des Empfangs oder erfährt er ihn später, so ist er von dem Empfang oder der Erlangung der Kenntnis an zur Herausgabe verpflichtet, wie wenn der Anspruch auf Herausgabe zu dieser Zeit rechtshängig geworden wäre.',
'823 I': 'Wer vorsätzlich oder fahrlässig das Leben, den Körper, die Gesundheit, die Freiheit, das Eigentum oder ein sonstiges Recht eines anderen widerrechtlich verletzt, ist dem anderen zum Ersatz des daraus entstehenden Schadens verpflichtet.',
'823 II': 'Die gleiche Verpflichtung trifft denjenigen, welcher gegen ein den Schutz eines anderen bezweckendes Gesetz verstößt. Ist nach dem Inhalt des Gesetzes ein Verstoß gegen dieses auch ohne Verschulden möglich, so tritt die Ersatzpflicht nur im Falle des Verschuldens ein.',
'823': '(1) Wer vorsätzlich oder fahrlässig das Leben, den Körper, die Gesundheit, die Freiheit, das Eigentum oder ein sonstiges Recht eines anderen widerrechtlich verletzt, ist dem anderen zum Ersatz des daraus entstehenden Schadens verpflichtet.',
'826': 'Wer in einer gegen die guten Sitten verstoßenden Weise einem anderen vorsätzlich Schaden zufügt, ist dem anderen zum Ersatz des Schadens verpflichtet.',
'828': '(1) Wer nicht das siebente Lebensjahr vollendet hat, ist für einen Schaden, den er einem anderen zufügt, nicht verantwortlich. (2) Wer das siebente, aber nicht das zehnte Lebensjahr vollendet hat, ist für den Schaden, den er bei einem Unfall mit einem Kraftfahrzeug, einer Schienenbahn oder einer Schwebebahn einem anderen zufügt, nicht verantwortlich. Dies gilt nicht, wenn er die Verletzung vorsätzlich herbeigeführt hat. (3) Wer das 18. Lebensjahr noch nicht vollendet hat, ist … für den Schaden … nicht verantwortlich, wenn er bei der Begehung der schädigenden Handlung nicht die zur Erkenntnis der Verantwortlichkeit erforderliche Einsicht hat.',
'831': '(1) Wer einen anderen zu einer Verrichtung bestellt, ist zum Ersatz des Schadens verpflichtet, den der andere in Ausführung der Verrichtung einem Dritten widerrechtlich zufügt. Die Ersatzpflicht tritt nicht ein, wenn der Geschäftsherr bei der Auswahl der bestellten Person … die im Verkehr erforderliche Sorgfalt beobachtet oder wenn der Schaden auch bei Anwendung dieser Sorgfalt entstanden sein würde.',
'832': '(1) Wer kraft Gesetzes zur Führung der Aufsicht über eine Person verpflichtet ist, die wegen Minderjährigkeit … der Beaufsichtigung bedarf, ist zum Ersatz des Schadens verpflichtet, den diese Person einem Dritten widerrechtlich zufügt. Die Ersatzpflicht tritt nicht ein, wenn er seiner Aufsichtspflicht genügt oder wenn der Schaden auch bei gehöriger Aufsichtsführung entstanden sein würde.',
'873': '(1) Zur Übertragung des Eigentums an einem Grundstück … ist die Einigung des Berechtigten und des anderen Teils über den Eintritt der Rechtsänderung und die Eintragung der Rechtsänderung in das Grundbuch erforderlich …',
'925': '(1) Die zur Übertragung des Eigentums an einem Grundstück nach § 873 erforderliche Einigung des Veräußerers und des Erwerbers (Auflassung) muss bei gleichzeitiger Anwesenheit beider Teile vor einer zuständigen Stelle erklärt werden.',
'929': 'Zur Übertragung des Eigentums an einer beweglichen Sache ist erforderlich, dass der Eigentümer die Sache dem Erwerber übergibt und beide darüber einig sind, dass das Eigentum übergehen soll.',
'932': '(1) Durch eine nach § 929 erfolgte Veräußerung wird der Erwerber auch dann Eigentümer, wenn die Sache nicht dem Veräußerer gehört, es sei denn, dass er zu der Zeit, zu der er nach diesen Vorschriften das Eigentum erwerben würde, nicht in gutem Glauben ist … (2) Der Erwerber ist nicht in gutem Glauben, wenn ihm bekannt oder infolge grober Fahrlässigkeit unbekannt ist, dass die Sache nicht dem Veräußerer gehört.',
'935': '(1) Der Erwerb des Eigentums auf Grund der §§ 932 bis 934 tritt nicht ein, wenn die Sache dem Eigentümer gestohlen worden, verloren gegangen oder sonst abhanden gekommen war … (2) Diese Vorschriften finden keine Anwendung auf Geld oder Inhaberpapiere sowie auf Sachen, die im Wege öffentlicher Versteigerung … veräußert werden.',
'937': '(1) Wer eine bewegliche Sache zehn Jahre im Eigenbesitz hat, erwirbt das Eigentum (Ersitzung).',
'946': 'Wird eine bewegliche Sache mit einem Grundstück dergestalt verbunden, dass sie wesentlicher Bestandteil des Grundstücks wird, so erstreckt sich das Eigentum an dem Grundstück auf diese Sache.',
'947': '(1) Werden bewegliche Sachen miteinander dergestalt verbunden, dass sie wesentliche Bestandteile einer einheitlichen Sache werden, so werden die bisherigen Eigentümer Miteigentümer dieser Sache …',
'951': '(1) Wer infolge der Vorschriften der §§ 946 bis 950 einen Rechtsverlust erleidet, kann von demjenigen, zu dessen Gunsten die Rechtsänderung eintritt, Vergütung in Geld nach den Vorschriften über die Herausgabe einer ungerechtfertigten Bereicherung fordern …',
'959': 'Eine bewegliche Sache wird herrenlos, wenn der Eigentümer in der Absicht, auf das Eigentum zu verzichten, den Besitz der Sache aufgibt.',
'971': '(1) Der Finder kann von dem Empfangsberechtigten einen Finderlohn verlangen. Der Finderlohn beträgt von dem Werte der Sache bis zu 500 Euro fünf vom Hundert, von dem Mehrwert drei vom Hundert …',
'985': 'Der Eigentümer kann von dem Besitzer die Herausgabe der Sache verlangen.',
'986': '(1) Der Besitzer kann die Herausgabe der Sache verweigern, wenn er oder der mittelbare Besitzer, von dem er sein Recht zum Besitz ableitet, dem Eigentümer gegenüber zum Besitz berechtigt ist.',
'1006': '(1) Zugunsten des Besitzers einer beweglichen Sache wird vermutet, dass er Eigentümer der Sache sei. Dies gilt jedoch nicht einem früheren Besitzer gegenüber, dem die Sache gestohlen worden, verloren gegangen oder sonst abhanden gekommen ist …',
'1008': 'Steht das Eigentum an einer Sache mehreren nach Bruchteilen zu, so gelten die Vorschriften der §§ 1009 bis 1011.',
'1629': '(1) Die elterliche Sorge umfasst die Vertretung des Kindes. Die Eltern vertreten das Kind gemeinschaftlich …',
'1643': '(1) Die Eltern bedürfen der Genehmigung des Familiengerichts in den Fällen, in denen ein Vormund nach den §§ 1848 bis 1854 der Genehmigung bedarf …',
'1850': 'Der Vormund bedarf der Genehmigung des Familiengerichts für 1. die Verfügung über ein Grundstück … 5. die Verpflichtung zu einer der in den Nummern 1 bis 4 genannten Verfügungen.',
'1939': 'Der Erblasser kann durch Testament einem anderen, ohne ihn als Erben einzusetzen, einen Vermögensvorteil zuwenden (Vermächtnis).',
'2147': 'Mit einem Vermächtnis kann der Erbe oder ein Vermächtnisnehmer beschwert werden.',
'2229': '(1) Ein Minderjähriger kann ein Testament erst errichten, wenn er das 16. Lebensjahr vollendet hat. (2) Der Minderjährige bedarf zur Errichtung eines Testaments nicht der Zustimmung seines gesetzlichen Vertreters.',
'2231': 'Ein Testament kann in ordentlicher Form errichtet werden 1. zur Niederschrift eines Notars, 2. durch eine vom Erblasser nach § 2247 abgegebene Erklärung.',
'2232': 'Zur Niederschrift eines Notars wird ein Testament errichtet, indem der Erblasser dem Notar seinen letzten Willen erklärt oder ihm eine Schrift mit der Erklärung übergibt …',
'2233': '(1) Ist der Erblasser minderjährig, so kann er das Testament nur durch eine Erklärung gegenüber dem Notar oder durch Übergabe einer offenen Schrift errichten.',
'2247': '(1) Der Erblasser kann ein Testament durch eine eigenhändig geschriebene und unterschriebene Erklärung errichten. (4) Wer minderjährig ist oder Geschriebenes nicht zu lesen vermag, kann ein Testament nicht nach obigen Vorschriften errichten.',
'HGB 1': '(1) Kaufmann im Sinne dieses Gesetzbuchs ist, wer ein Handelsgewerbe betreibt. (2) Handelsgewerbe ist jeder Gewerbebetrieb, es sei denn, dass das Unternehmen nach Art oder Umfang einen in kaufmännischer Weise eingerichteten Geschäftsbetrieb nicht erfordert.',
'HGB 15': '(1) Solange eine in das Handelsregister einzutragende Tatsache nicht eingetragen und bekanntgemacht ist, kann sie von demjenigen, in dessen Angelegenheiten sie einzutragen war, einem Dritten nicht entgegengesetzt werden, es sei denn, dass sie diesem bekannt war.',
'HGB 49': '(1) Die Prokura ermächtigt zu allen Arten von gerichtlichen und außergerichtlichen Geschäften und Rechtshandlungen, die der Betrieb eines Handelsgewerbes mit sich bringt. (2) Zur Veräußerung und Belastung von Grundstücken ist der Prokurist nur ermächtigt, wenn ihm diese Befugnis besonders erteilt ist.',
'HGB 50': '(1) Eine Beschränkung des Umfanges der Prokura ist Dritten gegenüber unwirksam.',
'HGB 53': '(1) Die Erteilung der Prokura ist von dem Inhaber des Handelsgeschäfts zur Eintragung in das Handelsregister anzumelden …',
'HGB 56': 'Wer in einem Laden oder in einem offenen Warenlager angestellt ist, gilt als ermächtigt zu Verkäufen und Empfangnahmen, die in einem derartigen Laden oder Warenlager gewöhnlich geschehen.',
'HGB 343': '(1) Handelsgeschäfte sind alle Geschäfte eines Kaufmanns, die zum Betriebe seines Handelsgewerbes gehören.',
'HGB 344': '(1) Die von einem Kaufmanne vorgenommenen Rechtsgeschäfte gelten im Zweifel als zum Betriebe seines Handelsgewerbes gehörig.',
'HGB 346': 'Unter Kaufleuten ist in Ansehung der Bedeutung und Wirkung von Handlungen und Unterlassungen auf die im Handelsverkehre geltenden Gewohnheiten und Gebräuche Rücksicht zu nehmen.',
'HGB 350': 'Auf eine Bürgschaft, ein Schuldversprechen oder ein Schuldanerkenntnis finden die Formvorschriften des § 766 Satz 1 und 2, des § 780 und des § 781 Satz 1 des Bürgerlichen Gesetzbuchs keine Anwendung, sofern die Bürgschaft auf der Seite des Bürgen … ein Handelsgeschäft ist.',
'HGB 362': '(1) Geht einem Kaufmanne, dessen Gewerbebetrieb die Besorgung von Geschäften für andere mit sich bringt, ein Antrag über die Besorgung solcher Geschäfte von jemand zu, mit dem er in Geschäftsverbindung steht, so ist er verpflichtet, unverzüglich zu antworten; sein Schweigen gilt als Annahme des Antrags.',
'HGB 377': '(1) Ist der Kauf für beide Teile ein Handelsgeschäft, so hat der Käufer die Ware unverzüglich nach der Ablieferung durch den Verkäufer, soweit dies nach ordnungsmäßigem Geschäftsgange tunlich ist, zu untersuchen und, wenn sich ein Mangel zeigt, dem Verkäufer unverzüglich Anzeige zu machen. (2) Unterlässt der Käufer die Anzeige, so gilt die Ware als genehmigt …',
'ProdHaftG 1': '(1) Wird durch den Fehler eines Produkts jemand getötet, sein Körper oder seine Gesundheit verletzt oder eine Sache beschädigt, so ist der Hersteller des Produkts verpflichtet, dem Geschädigten den daraus entstehenden Schaden zu ersetzen. Im Falle der Sachbeschädigung gilt dies nur, wenn eine andere Sache als das fehlerhafte Produkt beschädigt wird und diese andere Sache ihrer Art nach gewöhnlich für den privaten Ge- oder Verbrauch bestimmt … ist.',
'ProdHaftG 11': 'Im Falle der Sachbeschädigung hat der Geschädigte einen Schaden bis zu einer Höhe von 500 Euro selbst zu tragen.',
'GVG 23': 'Die Zuständigkeit der Amtsgerichte umfasst in bürgerlichen Rechtsstreitigkeiten …: 1. Streitigkeiten über Ansprüche, deren Gegenstand an Geld oder Geldeswert die Summe von 10.000 Euro nicht übersteigt …',
'GVG 71': '(1) Vor die Zivilkammern, einschließlich der Kammern für Handelssachen, gehören alle bürgerlichen Rechtsstreitigkeiten, die nicht den Amtsgerichten zugewiesen sind. (2) Die Landgerichte sind ohne Rücksicht auf den Wert des Streitgegenstandes ausschließlich zuständig 1. für die Ansprüche, die auf Grund der Beamtengesetze … erhoben werden, 2. für Ansprüche gegen Richter und Beamte wegen Überschreitung ihrer amtlichen Befugnisse …',
'GVG 119': '(1) Die Oberlandesgerichte sind in bürgerlichen Rechtsstreitigkeiten ferner zuständig für die Verhandlung und Entscheidung über die Rechtsmittel: 1. der Berufung und der Beschwerde gegen Entscheidungen der Amtsgerichte … 2. der Berufung und der Beschwerde gegen Entscheidungen der Landgerichte.',
'ZPO 78': '(1) Vor den Landgerichten und Oberlandesgerichten müssen sich die Parteien durch einen Rechtsanwalt vertreten lassen …',
'StVG 7': '(1) Wird bei dem Betrieb eines Kraftfahrzeugs … ein Mensch getötet, der Körper oder die Gesundheit eines Menschen verletzt oder eine Sache beschädigt, so ist der Halter verpflichtet, dem Verletzten den daraus entstehenden Schaden zu ersetzen.',
};
(function(){
  const N = window.WPR_NORMEN, LAW = /(HGB|ProdHaftG|StVG|GVG|ZPO|StVO|StGB|BetrVG|GmbHG)/;
  const re = /§§?\s*((?:\d+[a-z]?(?:\s+[IVX]+\b)?(?:\s+\d+\b)?(?:\s+(?:Nr|Alt|Hs)\.?\s*\d+)?(?:\s*(?:,|und|–|-|i\.\s?V\.\s?m\.)\s*(?=\d))?)+)(\s*(?:HGB|ProdHaftG|GVG|ZPO|StVG|StVO|StGB|BetrVG|GmbHG))?/g;
  function refs(s) {
    const out = []; let m; re.lastIndex = 0;
    while ((m = re.exec(s))) {
      const law = (m[2] || '').trim();
      const parts = m[1].split(/,|und|–|-|i\.\s?V\.\s?m\./).filter(p => p.trim());
      parts.forEach((p, i) => {
        const mm = p.trim().match(/^(\d+[a-z]?)(?:\s+([IVX]+)\b)?/);
        if (mm) out.push({ law: i === parts.length - 1 ? law : '', p: mm[1], a: mm[2] || '' });
      });
    }
    return out;
  }
  function look(r) {
    const pre = r.law ? r.law + ' ' : '';
    if (r.law && !/HGB|ProdHaftG|StVG|GVG|ZPO/.test(r.law)) return null;
    const k1 = pre + r.p + (r.a ? ' ' + r.a : ''), k2 = pre + r.p;
    if (N[k1]) return { k: k1, t: N[k1] };
    if (N[k2]) return { k: k2, t: N[k2] };
    const k3 = Object.keys(N).find(k => k.startsWith(k2 + ' '));
    return k3 ? { k: k3, t: N[k3] } : null;
  }
  const label = k => { const m = k.match(/^(?:(\S+) )?(\d+[a-z]?)(?: ([IVX]+))?$/); if (!m) return '§ ' + k; const law = /^[A-Z]/.test(k) ? k.split(' ')[0] : 'BGB'; const num = /^[A-Z]/.test(k) ? k.split(' ').slice(1).join(' ') : k; return '§ ' + num + ' ' + law; };
  window.WPR_NORMS_FOR = function (texts, max) {
    const seen = new Set(), out = [];
    for (const s of texts) for (const r of refs(s || '')) {
      const h = look(r); if (!h) continue;
      const base = h.k.replace(/ [IVX]+$/, '');
      if (seen.has(h.k) || seen.has(base)) continue;
      seen.add(h.k); seen.add(base); out.push({ n: label(h.k), t: h.t });
      if (out.length >= (max || 2)) return out;
    }
    return out;
  };
})();
